"  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [customerAddress, setCustomerAddress] = useState('');
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [kotNote, setKOTNote] = useState('');
  const [coversCount, setCoversCount] = useState('');
  const [ebillEnabled, setEbillEnabled] = useState(false);
  const [searchResults, setSearchResults] = useState([]);
  const [showSearchResults, setShowSearchResults] = useState(false);
  const [activeSearchResultIndex, setActiveSearchResultIndex] = useState(-1);

  useEffect(() => {
    setActiveSearchResultIndex(-1);
    if (justSelectedCustomerRef.current) {
      justSelectedCustomerRef.current = false;
      return;
    }
    if (!customerPhone || customerPhone.length < 3) {
      setSearchResults([]);
      setShowSearchResults(false);
      return;
    }

    const delayDebounce = setTimeout(async () => {
      try {
        const response = await posService.searchCustomers(customerPhone);
        if (response.data && Array.isArray(response.data)) {
          setSearchResults(response.data);
          setShowSearchResults(response.data.length > 0);
        }
      } catch (err) {
        console.error("Error searching customers:", err);
      }
    }, 300);

    return () => clearTimeout(delayDebounce);
  }, [customerPhone]);

  useEffect(() => {
    if (!customerPhone) {
      setSelectedCustomer(null);
      setRedeemedPoints(0);
    }
  }, [customerPhone]);"

